// Bundles src/audio/webviewEntry.ts (the DSP pipeline + Web Audio decode
// glue) into a single self-contained script, then writes it out as a
// plain importable TS string constant. Re-run this whenever src/dsp or
// src/audio/webviewEntry.ts changes -- Metro does not do this step
// automatically. Emitting a .ts string constant (rather than a raw .js
// asset file) sidesteps Metro's asset-loading config entirely: it's just
// bundled as ordinary string data, never executed by Metro/RN itself --
// only fed into the WebView's `source={{ html }}` at runtime.
import * as esbuild from 'esbuild';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import fs from 'node:fs/promises';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');

const result = await esbuild.build({
  entryPoints: [path.join(root, 'src/audio/webviewEntry.ts')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: 'es2017',
  minify: true,
  write: false,
  logLevel: 'info',
});

const js = result.outputFiles[0].text;
const outPath = path.join(root, 'src/audio/generatedWebviewBundle.ts');
const header = '// AUTO-GENERATED by scripts/build-webview-bundle.mjs -- do not edit by hand.\n';
await fs.writeFile(outPath, `${header}export const WEBVIEW_BUNDLE_JS = ${JSON.stringify(js)};\n`);
console.log(`Wrote ${outPath} (${js.length} bytes)`);
